package io.github.ningpp.compat;

/** Replacement for System.Runtime.InteropServices.ExternalException (generated by CSharpToJava converter). */
public class ExternalException extends SystemException {
    public ExternalException() { super(); }
    public ExternalException(String message) { super(message); }
    public ExternalException(String message, Throwable cause) { super(message, cause); }
}
